SELECT O.ID, O.NOME, COUNT(DISTINCT V.ID) VIDEOS, MIN(CASE WHEN V.ID IS NOT NULL THEN L.ID END) INDICADO_ID FROM (SELECT N.ID, N.NOME, COALESCE(M.OBRA, N.NOME) OBRA FROM LIVROS_NOMES N LEFT JOIN OBRA_DE M ON M.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = 'SAGRADO') O LEFT JOIN LIVROS_INDICADOS L ON L.TITULO COLLATE utf8mb4_0900_ai_ci = O.NOME LEFT JOIN VIDEOS V ON V.ID = L.VIDEO_ID AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) WHERE O.OBRA COLLATE utf8mb4_0900_ai_ci = '{{obra}}' GROUP BY O.ID, O.NOME ORDER BY VIDEOS DESC, O.NOME